"""Product catalog used by the storefront.

get_product(product_id) -> dict    {"id": int, "name": str, "price": float, "currency": str}
update_price(product_id, price)    changes the price in the inventory service

Reads are cached in Redis (shared by every storefront process) with a
5 minute TTL.  Writes go straight through to the inventory service and
evict the product's cache entry, so the next read in any process sees
the fresh price.
"""
import json
import urllib.request

import redis

INVENTORY_URL = "http://127.0.0.1:8000"

REDIS_HOST = "127.0.0.1"
REDIS_PORT = 6379
REDIS_DB = 0

PRODUCT_TTL_SECONDS = 300  # cached products expire after 5 minutes

_PREFIX = "catalog:product:"
_CACHE_DISABLED = False

try:
    _redis = redis.Redis(
        host=REDIS_HOST,
        port=REDIS_PORT,
        db=REDIS_DB,
        decode_responses=True,
        socket_timeout=1,
        socket_connect_timeout=1,
    )
    _redis.ping()
except Exception:
    # Redis unavailable: degrade to direct inventory calls instead of failing.
    _redis = None
    _CACHE_DISABLED = True


def _cache_key(product_id: int) -> str:
    return f"{_PREFIX}{int(product_id)}"


def _cache_get(product_id: int):
    if _CACHE_DISABLED:
        return None
    try:
        raw = _redis.get(_cache_key(product_id))
    except Exception:
        return None
    if raw is None:
        return None
    try:
        return json.loads(raw)
    except (ValueError, TypeError):
        # Unreadable entry: treat as a miss and overwrite it with a fresh one.
        try:
            _redis.delete(_cache_key(product_id))
        except Exception:
            pass
        return None


def _cache_set(product_id: int, product: dict) -> None:
    if _CACHE_DISABLED:
        return
    try:
        _redis.set(_cache_key(product_id), json.dumps(product), ex=PRODUCT_TTL_SECONDS)
    except Exception:
        pass  # cache write failures must never break reads/writes


def _cache_delete(product_id: int) -> None:
    if _CACHE_DISABLED:
        return
    try:
        _redis.delete(_cache_key(product_id))
    except Exception:
        pass


def get_product(product_id: int) -> dict:
    cached = _cache_get(product_id)
    if cached is not None:
        return cached

    with urllib.request.urlopen(f"{INVENTORY_URL}/products/{int(product_id)}", timeout=10) as resp:
        product = json.load(resp)

    _cache_set(product_id, product)
    return product


def update_price(product_id: int, price: float) -> None:
    body = json.dumps({"price": price}).encode()
    req = urllib.request.Request(
        f"{INVENTORY_URL}/products/{int(product_id)}",
        data=body,
        method="PUT",
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=10) as resp:
        resp.read()

    # Evict the cached copy so the next get_product() in any process reads
    # the new price from the inventory service.
    _cache_delete(product_id)
